			return new List<OpenXmlAttribute>();
		}

		private void GetAttributes(ICollection<OpenXmlAttribute> attributes)
		{
			if (attributes == null)
			{
				throw new ArgumentNullException("attributes");
			}
			if (!HasAttributes)
			{
				return;
			}
			int num = 0;
			if (Attributes != null)
			{
				for (num = 0; num < Attributes.Length; num++)
				{
					if (Attributes[num] != null)
					{
						OpenXmlAttribute item = new OpenXmlAttribute(NamespaceIdMap.GetNamespacePrefix(AttributeNamespaceIds[num]), AttributeTagNames[num], NamespaceIdMap.GetNamespaceUri(AttributeNamespaceIds[num]), Attributes[num].ToString());
						attributes.Add(item);
					}
				}
			}
			foreach (OpenXmlAttribute extendedAttribute in ExtendedAttributes)
			{
				OpenXmlAttribute item = new OpenXmlAttribute(extendedAttribute.Prefix, extendedAttribute.LocalName, extendedAttribute.NamespaceUri, extendedAttribute.Value);
				attributes.Add(item);
			}
			if (MCAttributes != null)
			{
				AddMCAttributes(attributes);
			}
		}

		public void SetAttribute(OpenXmlAttribute openXmlAttribute)
		{
			if (string.IsNullOrEmpty(openXmlAttribute.LocalName))
			{
				throw new ArgumentOutOfRangeException("openXmlAttribute", ExceptionMessages.LocalNameIsNull);
			}
			if (openXmlAttribute.Prefix == "xmlns")
			{
				throw new InvalidOperationException(ExceptionMessages.CannotSetAttribute);
			}
			MakeSureParsed();
			if (TrySetFixedAttribute(openXmlAttribute.NamespaceUri, openXmlAttribute.LocalName, openXmlAttribute.Value) || (openXmlAttribute.NamespaceUri == AlternateContent.MarkupCompatibilityNamespace && LoadMCAttribute(openXmlAttribute.LocalName, openXmlAttribute.Value)))
			{
				return;
			}
			int num = 0;
			if (ExtendedAttributesField != null)
			{
				foreach (OpenXmlAttribute item2 in ExtendedAttributesField)
				{
					if (item2.LocalName == openXmlAttribute.LocalName && item2.NamespaceUri == openXmlAttribute.NamespaceUri)
					{
						ExtendedAttributesField.RemoveAt(num);
						break;
					}
					num++;
				}
			}
			if (ExtendedAttributesField == null)
			{
				ExtendedAttributesField = new List<OpenXmlAttribute>();
			}
			OpenXmlAttribute item = new OpenXmlAttribute(openXmlAttribute.Prefix, openXmlAttribute.LocalName, openXmlAttribute.NamespaceUri, openXmlAttribute.Value);
			ExtendedAttributesField.Add(item);
		}

		public void RemoveAttribute(string localName, string namespaceUri)
		{
			if (localName == null)
			{
				throw new ArgumentNullException("localName");
			}
			if (namespaceUri == null)
			{
				namespaceUri = string.Empty;
			}
			if (localName == string.Empty)
			{
				throw new ArgumentOutOfRangeException("localName", ExceptionMessages.StringIsEmpty);
			}
			if (!HasAttributes)
			{
				return;
			}
			bool flag = false;
			if (FixedAttributeTotal > 0)
			{
				int num = TryFindAttributeIndex(namespaceUri, localName);
				if (num >= 0)
				{
					FixedAttributesArray[num] = null;
					flag = true;
				}
			}
			if (!flag)
			{
				int num2 = 0;
				if (ExtendedAttributesField != null)
				{
					foreach (OpenXmlAttribute item in ExtendedAttributesField)
					{
						if (item.LocalName == localName && item.NamespaceUri == namespaceUri)
						{
							ExtendedAttributesField.RemoveAt(num2);
							return;
						}
						num2++;
					}
				}
			}
			if (namespaceUri == AlternateContent.MarkupCompatibilityNamespace)
			{
				RemoveMCAttribute(localName);
			}
		}

