		public virtual void WriteTo(XmlWriter xmlWriter)
		{
			if (xmlWriter == null)
			{
				throw new ArgumentNullException("xmlWriter");
			}
			if (XmlParsed)
			{
				string text = LookupPrefixLocal(NamespaceUri);
				if (string.IsNullOrEmpty(text))
				{
					text = xmlWriter.LookupPrefix(NamespaceUri);
				}
				if (string.IsNullOrEmpty(text))
				{
					text = NamespaceIdMap.GetNamespacePrefix(NamespaceId);
				}
				xmlWriter.WriteStartElement(text, LocalName, NamespaceUri);
				WriteAttributesTo(xmlWriter);
