		private static ElementOrder GetOrder(OpenXmlElement element1, OpenXmlElement element2)
		{
			if (element1.Parent == null && element2.Parent == null)
			{
				return ElementOrder.NotInSameTree;
			}
			if (object.ReferenceEquals(element1.Parent, element2.Parent))
			{
				return GetSiblingOrder(element1, element2);
			}
			Stack<OpenXmlElement> stack = new Stack<OpenXmlElement>();
			Stack<OpenXmlElement> stack2 = new Stack<OpenXmlElement>();
			stack.Push(element1);
			stack2.Push(element2);
			foreach (OpenXmlElement item in element1.Ancestors())
			{
				stack.Push(item);
			}
			foreach (OpenXmlElement item2 in element2.Ancestors())
			{
				stack2.Push(item2);
			}
			OpenXmlElement openXmlElement = stack.Pop();
			OpenXmlElement openXmlElement2 = stack2.Pop();
			if (openXmlElement == openXmlElement2)
			{
				while (stack.Count > 0 && stack2.Count > 0)
				{
					openXmlElement = stack.Pop();
					openXmlElement2 = stack2.Pop();
					ElementOrder siblingOrder = GetSiblingOrder(openXmlElement, openXmlElement2);
					if (siblingOrder != 0)
					{
						return siblingOrder;
					}
				}
				if (stack.Count == 0)
				{
					return ElementOrder.Before;
				}
				return ElementOrder.After;
			}
			return ElementOrder.NotInSameTree;
		}

		private static ElementOrder GetSiblingOrder(OpenXmlElement element1, OpenXmlElement element2)
		{
			if (element1 == element2)
			{
				return ElementOrder.Same;
			}
			for (OpenXmlElement openXmlElement = element1.NextSibling(); openXmlElement != null; openXmlElement = openXmlElement.NextSibling())
			{
				if (object.ReferenceEquals(openXmlElement, element2))
				{
					return ElementOrder.Before;
				}
			}
			return ElementOrder.After;
		}

		internal virtual void WriteAttributesTo(XmlWriter xmlWriter)
		{
			if (NamespaceDeclField != null)
			{
				foreach (KeyValuePair<string, string> item in NamespaceDeclField)
				{
					xmlWriter.WriteAttributeString("xmlns", item.Key, "http://www.w3.org/2000/xmlns/", item.Value);
				}
			}
			if (!XmlParsed || !HasAttributes)
			{
				return;
			}
			int num = 0;
			if (Attributes != null)
			{
				OpenXmlSimpleType[] attributes = Attributes;
				foreach (OpenXmlSimpleType openXmlSimpleType in attributes)
				{
					if (openXmlSimpleType != null)
					{
						string namespaceUri = NamespaceIdMap.GetNamespaceUri(AttributeNamespaceIds[num]);
						string text = string.Empty;
						if (!string.IsNullOrEmpty(namespaceUri))
						{
							text = xmlWriter.LookupPrefix(namespaceUri);
							if (string.IsNullOrEmpty(text))
							{
								text = NamespaceIdMap.GetNamespacePrefix(AttributeNamespaceIds[num]);
							}
						}
						xmlWriter.WriteStartAttribute(text, AttributeTagNames[num], namespaceUri);
						xmlWriter.WriteString(openXmlSimpleType.InnerText);
						xmlWriter.WriteEndAttribute();
					}
					num++;
				}
			}
			foreach (OpenXmlAttribute extendedAttribute in ExtendedAttributes)
			{
				xmlWriter.WriteAttributeString(extendedAttribute.Prefix, extendedAttribute.LocalName, extendedAttribute.NamespaceUri, extendedAttribute.Value);
			}
			WriteMCAttribute(xmlWriter);
		}

