		internal int TryFindAttributeIndex(string namespaceUri, string tagName)
		{
			byte id = 0;
			if (namespaceUri != null && NamespaceIdMap.TryGetNamespaceId(namespaceUri, out id))
			{
				for (int i = 0; i < AttributeTagNames.Length; i++)
				{
					string text = AttributeTagNames[i];
					if (text.Equals(tagName) && AttributeNamespaceIds[i] == id)
					{
						return i;
					}
				}
			}
			return -1;
		}

		internal bool TrySetFixedAttribute(string namespaceUri, string localName, string value)
		{
			if (FixedAttributeTotal > 0)
			{
				int num = TryFindAttributeIndex(namespaceUri, localName);
				if (num >= 0)
				{
					OpenXmlSimpleType openXmlSimpleType = AttributeFactory(namespaceUri, localName);
					FixedAttributesArray[num] = openXmlSimpleType;
					openXmlSimpleType.InnerText = value;
					return true;
				}
			}
			return false;
		}

		internal virtual void LoadAttributes(XmlReader xmlReader)
		{
			if (!xmlReader.HasAttributes)
			{
				return;
			}
			while (xmlReader.MoveToNextAttribute())
			{
				if (TrySetFixedAttribute(xmlReader.NamespaceURI, xmlReader.LocalName, xmlReader.Value) || (xmlReader.NamespaceURI == AlternateContent.MarkupCompatibilityNamespace && LoadMCAttribute(xmlReader.LocalName, xmlReader.Value)))
				{
					continue;
				}
				if (!(xmlReader.NamespaceURI == "http://www.w3.org/2000/xmlns/"))
				{
					if (ExtendedAttributesField == null)
					{
						ExtendedAttributesField = new List<OpenXmlAttribute>();
					}
					ExtendedAttributesField.Add(new OpenXmlAttribute(xmlReader.Prefix, xmlReader.LocalName, xmlReader.NamespaceURI, xmlReader.Value));
				}
				else if (!string.IsNullOrEmpty(xmlReader.Prefix))
				{
					if (NamespaceDeclField == null)
					{
						NamespaceDeclField = new List<KeyValuePair<string, string>>();
					}
					NamespaceDeclField.Add(new KeyValuePair<string, string>(xmlReader.LocalName, xmlReader.Value));
				}
			}
			RemoveAttributesBasedonMC();
			xmlReader.MoveToElement();
		}

		internal bool PushMcContext(XmlReader xmlReader)
		{
			if (OpenXmlElementContext != null && OpenXmlElementContext.MCSettings.ProcessMode != 0)
			{
				OpenXmlElementContext.MCContext.LookupNamespaceDelegate = xmlReader.LookupNamespace;
				MarkupCompatibilityAttributes markupCompatibilityAttributes = LoadMCAttribute(xmlReader);
				if (markupCompatibilityAttributes != null)
				{
					OpenXmlElementContext.MCContext.PushMCAttributes(markupCompatibilityAttributes);
					if (OpenXmlElementContext.ACBlockLevel == 0)
					{
						CheckMustUnderstandAttr(xmlReader, markupCompatibilityAttributes, OpenXmlElementContext.MCSettings);
					}
					return true;
				}
			}
			return false;
		}

		internal void PopMcContext()
		{
			if (OpenXmlElementContext != null && OpenXmlElementContext.MCSettings.ProcessMode != 0)
			{
				OpenXmlElementContext.MCContext.PopMCAttributes();
			}
		}

		internal static void CheckMustUnderstandAttr(XmlReader reader, MarkupCompatibilityAttributes mcAttributes, MarkupCompatibilityProcessSettings mcSettings)
		{
			if (mcAttributes.MustUnderstand == null || string.IsNullOrEmpty(mcAttributes.MustUnderstand.Value))
			{
				return;
			}
			string[] array = mcAttributes.MustUnderstand.Value.Trim().Split(new char[1] { ' ' });
			string[] array2 = array;
			foreach (string text in array2)
			{
				string text2 = reader.LookupNamespace(text);
				if (string.IsNullOrEmpty(text2))
				{
					string message = string.Format(CultureInfo.CurrentCulture, ExceptionMessages.UnknowMCContent, new object[1] { mcAttributes.MustUnderstand.Value });
					throw new InvalidMCContentException(message);
				}
				if (!NamespaceIdMap.IsInFileFormat(text2, mcSettings.TargetFileFormatVersions))
				{
					string message2 = string.Format(CultureInfo.CurrentCulture, ExceptionMessages.NsNotUnderStand, new object[1] { text });
					throw new NamespaceNotUnderstandException(message2);
				}
			}
		}

		internal void CheckMustUnderstandAttr()
		{
			if (MCAttributes == null || OpenXmlElementContext.MCSettings.ProcessMode == MarkupCompatibilityProcessMode.NoProcess)
			{
				return;
			}
			if (MCAttributes.MustUnderstand != null && !string.IsNullOrEmpty(MCAttributes.MustUnderstand.Value))
			{
				string[] array = MCAttributes.MustUnderstand.Value.Trim().Split(new char[1] { ' ' });
				string[] array2 = array;
				foreach (string text in array2)
				{
					string text2 = LookupNamespace(text);
					if (string.IsNullOrEmpty(text2))
					{
						string message = string.Format(CultureInfo.CurrentCulture, ExceptionMessages.UnknowMCContent, new object[1] { MCAttributes.MustUnderstand.Value });
						throw new InvalidMCContentException(message);
					}
					if (!NamespaceIdMap.IsInFileFormat(text2, OpenXmlElementContext.MCSettings.TargetFileFormatVersions))
					{
						string message2 = string.Format(CultureInfo.CurrentCulture, ExceptionMessages.NsNotUnderStand, new object[1] { text });
						throw new NamespaceNotUnderstandException(message2);
					}
				}
			}
			foreach (OpenXmlElement childElement in ChildElements)
			{
				childElement.CheckMustUnderstandAttr();
			}
		}

		internal void Load(XmlReader xmlReader, OpenXmlLoadMode loadMode)
		{
			switch (loadMode)
			{
			case OpenXmlLoadMode.Full:
				Populate(xmlReader, loadMode);
				break;
			case OpenXmlLoadMode.Lazy:
				if (OpenXmlElementContext != null && xmlReader.Depth < OpenXmlElementContext.LazySteps)
				{
					Populate(xmlReader, loadMode);
				}
				else
				{
					LazyLoad(xmlReader);
				}
				break;
			}
		}

