		internal OpenXmlCompositeElement GetContentFromACBlock(AlternateContent acblk, FileFormatVersions format)
		{
			foreach (AlternateContentChoice item in acblk.ChildElements.OfType<AlternateContentChoice>())
			{
				if (item.Requires == null)
				{
					continue;
				}
				string text = item.Requires.InnerText.Trim();
				if (string.IsNullOrEmpty(text))
				{
					continue;
				}
				bool flag = true;
				string[] array = text.Split(new char[1] { ' ' });
				foreach (string text2 in array)
				{
					string text3 = item.LookupNamespace(text2);
					if (text3 == null)
					{
						if (_noExceptionOnError)
						{
							flag = false;
							break;
						}
						string message = string.Format(CultureInfo.CurrentUICulture, ExceptionMessages.UnknowMCContent, new object[1] { text2 });
						throw new InvalidMCContentException(message);
					}
					if (!NamespaceIdMap.IsInFileFormat(text3, format))
					{
						flag = false;
						break;
					}
				}
				if (flag)
				{
					return item;
				}
			}
			AlternateContentFallback firstChild = acblk.GetFirstChild<AlternateContentFallback>();
			if (firstChild != null)
			{
				return firstChild;
			}
			return null;
		}
	}
