				MediaDataPartType.Mpg => ".mpg", 
				MediaDataPartType.MpegVideo => ".mpeg", 
				MediaDataPartType.Wmv => ".wmv", 
				MediaDataPartType.Wmx => ".wmx", 
				MediaDataPartType.Wvx => ".wvx", 
				MediaDataPartType.Quicktime => ".mov", 
