				int num = 0;
				int num2 = -1;
				XmlNodeType xmlNodeType = XmlNodeType.Text;
				if (xmlReader.NodeType != XmlNodeType.EndElement)
				{
					while (!xmlReader.EOF && xmlReader.NodeType != XmlNodeType.EndElement)
					{
						if (string.IsNullOrEmpty(RawInnerText) && (xmlReader.NodeType == XmlNodeType.Text || xmlReader.NodeType == XmlNodeType.CDATA || xmlReader.NodeType == XmlNodeType.SignificantWhitespace))
						{
							RawInnerText = xmlReader.Value;
