			using (StringReader input = new StringReader(outerXml))
			{
				XmlReaderSettings settings = new XmlReaderSettings();
				using XmlReader xmlReader = XmlReader.Create(input, settings);
				xmlReader.Read();
				if (xmlReader.NodeType != nodeType)
				{
