		internal void LoadOuterXml(XmlReader xmlReader)
		{
			switch (xmlReader.NodeType)
			{
			case XmlNodeType.XmlDeclaration:
				Value = xmlReader.Value;
				break;
			case XmlNodeType.Text:
				Value = xmlReader.Value;
				base.RawOuterXml = xmlReader.Value;
				break;
			case XmlNodeType.CDATA:
				Value = xmlReader.Value;
				base.RawOuterXml = string.Format(CultureInfo.InvariantCulture, "<![CDATA[{0}]]>", new object[1] { xmlReader.Value });
				break;
			case XmlNodeType.SignificantWhitespace:
				Value = xmlReader.Value;
				base.RawOuterXml = xmlReader.Value;
				break;
			case XmlNodeType.ProcessingInstruction:
				Value = xmlReader.Value;
				base.RawOuterXml = string.Format(CultureInfo.InvariantCulture, "<?{0} {1}?>", new object[2] { xmlReader.Name, xmlReader.Value });
				break;
			case XmlNodeType.Comment:
				Value = xmlReader.Value;
				base.RawOuterXml = string.Format(CultureInfo.InvariantCulture, "<!--{0}-->", new object[1] { xmlReader.Value });
				break;
			case XmlNodeType.EntityReference:
				base.RawOuterXml = xmlReader.Name;
				break;
			case XmlNodeType.None:
			case XmlNodeType.Element:
			case XmlNodeType.Attribute:
			case XmlNodeType.Entity:
			case XmlNodeType.Document:
			case XmlNodeType.DocumentType:
			case XmlNodeType.DocumentFragment:
			case XmlNodeType.Notation:
			case XmlNodeType.Whitespace:
			case XmlNodeType.EndElement:
			case XmlNodeType.EndEntity:
				break;
			}
		}

		internal override void LoadAttributes(XmlReader xmlReader)
		{
		}

		internal override void Populate(XmlReader xmlReader, OpenXmlLoadMode loadMode)
		{
			LoadOuterXml(xmlReader);
			xmlReader.Read();
		}

