namespace DocumentFormat.OpenXml.Packaging
{
	public abstract class OpenXmlPackage : OpenXmlPartContainer, IDisposable
	{
		internal class PartUriHelper
		{
			private Dictionary<string, int> _sequenceNumbers = new Dictionary<string, int>(20);

			private Dictionary<string, int> _reservedUri = new Dictionary<string, int>();

			private bool IsReservedUri(Uri uri)
			{
				string key = uri.OriginalString.ToUpperInvariant();
				return _reservedUri.ContainsKey(key);
			}

			internal void AddToReserveUri(Uri partUri)
			{
				string key = partUri.OriginalString.ToUpperInvariant();
				_reservedUri.Add(key, 0);
			}

			internal void ReserveUri(string contentType, Uri partUri)
			{
				GetNextSequenceNumber(contentType);
				AddToReserveUri(PackUriHelper.GetNormalizedPartUri(partUri));
			}

			internal Uri GetUniquePartUri(string contentType, Uri parentUri, string targetPath, string targetName, string targetExt)
			{
				Uri uri2;
				do
				{
					string nextSequenceNumber = GetNextSequenceNumber(contentType);
					string uriString = System.IO.Path.Combine(targetPath, targetName + nextSequenceNumber + targetExt);
					Uri uri = new Uri(uriString, UriKind.RelativeOrAbsolute);
					uri2 = PackUriHelper.ResolvePartUri(parentUri, uri);
				}
				while (IsReservedUri(uri2));
				AddToReserveUri(uri2);
				return uri2;
			}

			internal Uri GetUniquePartUri(string contentType, Uri parentUri, Uri targetUri)
			{
				Uri uri = PackUriHelper.ResolvePartUri(parentUri, targetUri);
				if (IsReservedUri(uri))
				{
					string targetPath = ".";
					string fileNameWithoutExtension = System.IO.Path.GetFileNameWithoutExtension(targetUri.OriginalString);
					string extension = System.IO.Path.GetExtension(targetUri.OriginalString);
					uri = GetUniquePartUri(contentType, uri, targetPath, fileNameWithoutExtension, extension);
				}
				else
				{
					AddToReserveUri(uri);
				}
				return uri;
			}

			private string GetNextSequenceNumber(string contentType)
			{
				if (_sequenceNumbers.ContainsKey(contentType))
				{
					_sequenceNumbers[contentType]++;
					return Convert.ToString(_sequenceNumbers[contentType], 16);
				}
				_sequenceNumbers.Add(contentType, 1);
				return "";
			}
