		private void Load()
		{
			try
			{
				Dictionary<Uri, OpenXmlPart> loadedParts = new Dictionary<Uri, OpenXmlPart>();
				PackageRelationshipCollection relationships = _metroPackage.GetRelationships();
				bool flag = false;
				foreach (PackageRelationship item in relationships)
				{
					if (item.RelationshipType == MainPartRelationshipType)
					{
						flag = true;
						Uri uri = PackUriHelper.ResolvePartUri(new Uri("/", UriKind.Relative), item.TargetUri);
						PackagePart part = Package.GetPart(uri);
						if (!IsValidMainPartContentType(part.ContentType))
						{
							OpenXmlPackageException ex = new OpenXmlPackageException(ExceptionMessages.InvalidPackageType);
							throw ex;
						}
						MainPartContentType = part.ContentType;
						break;
					}
				}
				if (!flag)
				{
					OpenXmlPackageException ex2 = new OpenXmlPackageException(ExceptionMessages.NoMainPart);
					throw ex2;
				}
				LoadReferencedPartsAndRelationships(this, null, relationships, loadedParts);
			}
			catch (OpenXmlPackageException)
			{
				Close();
				throw;
			}
			catch (Exception)
			{
				Close();
				throw;
			}
		}

