		internal void ChangeDocumentTypeInternal<T>() where T : OpenXmlPart
		{
			ThrowIfObjectDisposed();
			T subPartOfType = GetSubPartOfType<T>();
			MemoryStream memoryStream = null;
			ExtendedPart extendedPart = null;
