			ReferenceRelationship[] source;
			try
			{
				using (Stream stream = subPartOfType.GetStream())
				{
					if (stream.Length > int.MaxValue)
					{
						throw new OpenXmlPackageException(ExceptionMessages.DocumentTooBig);
					}
					memoryStream = new MemoryStream(Convert.ToInt32(stream.Length));
					OpenXmlPart.CopyStream(stream, memoryStream);
				}
				extendedPart = AddExtendedPart("http://temp", MainPartContentType, ".xml");
				foreach (KeyValuePair<string, OpenXmlPart> childrenPart in subPartOfType.ChildrenParts)
				{
					dictionary.Add(childrenPart.Key, childrenPart.Value);
				}
				source = subPartOfType.ReferenceRelationshipList.ToArray();
			}
			catch (OpenXmlPackageException innerException)
			{
				throw new OpenXmlPackageException(ExceptionMessages.CannotChangeDocumentType, innerException);
			}
			catch (SystemException innerException2)
			{
				throw new OpenXmlPackageException(ExceptionMessages.CannotChangeDocumentType, innerException2);
			}
			try
			{
				Uri uri = subPartOfType.Uri;
				string idOfPart = GetIdOfPart(subPartOfType);
				base.ChildrenParts.Remove(idOfPart);
				DeleteRelationship(idOfPart);
				subPartOfType.Destroy();
				T val = (T)Activator.CreateInstance(typeof(T), nonPublic: true);
				val.CreateInternal2(this, null, MainPartContentType, uri);
				string key = AttachChild(val, idOfPart);
				base.ChildrenParts.Add(key, val);
				memoryStream.Position = 0L;
				val.FeedData(memoryStream);
				foreach (KeyValuePair<string, OpenXmlPart> item in dictionary)
				{
					val.AttachChild(item.Value, item.Key);
					val.ChildrenParts.Add(item);
				}
				foreach (ExternalRelationship item2 in source.OfType<ExternalRelationship>())
				{
					val.AddExternalRelationship(item2.RelationshipType, item2.Uri, item2.Id);
				}
				foreach (HyperlinkRelationship item3 in source.OfType<HyperlinkRelationship>())
				{
					val.AddHyperlinkRelationship(item3.Uri, item3.IsExternal, item3.Id);
				}
				foreach (DataPartReferenceRelationship item4 in source.OfType<DataPartReferenceRelationship>())
				{
					val.AddDataPartReferenceRelationship(item4);
				}
				idOfPart = GetIdOfPart(extendedPart);
				base.ChildrenParts.Remove(idOfPart);
				DeleteRelationship(idOfPart);
				extendedPart.Destroy();
			}
			catch (OpenXmlPackageException innerException3)
			{
				throw new OpenXmlPackageException(ExceptionMessages.CannotChangeDocumentType, innerException3);
			}
			catch (SystemException innerException4)
			{
				throw new OpenXmlPackageException(ExceptionMessages.CannotChangeDocumentTypeSerious, innerException4);
			}
		}

