				OpenXmlPart openXmlPart = CreateOpenXmlPart(relationshipType);
				openXmlPart.CreateInternal(this, null, contentType, null);
				string key = AttachChild(openXmlPart);
				base.ChildrenParts.Add(key, openXmlPart);
				return openXmlPart;
			}
			throw new ArgumentOutOfRangeException("relationshipType");
		}

