					continue;
				}
				foreach (KeyValuePair<string, string> item2 in item.NamespaceDeclField)
				{
					if (!dictionary.ContainsKey(item2.Key))
					{
						dictionary.Add(item2.Key, item2.Value);
					}
				}
			}
			foreach (KeyValuePair<string, string> item3 in dictionary)
			{
				if (!string.IsNullOrEmpty(item3.Key) && base.NamespaceDeclField != null && string.IsNullOrEmpty(LookupPrefixLocal(item3.Value)) && string.IsNullOrEmpty(LookupNamespaceLocal(item3.Key)))
