				GetElementInformation();
				break;
			case ElementState.End:
			case ElementState.MiscNode:
				_xmlReader.Skip();
				_elementStack.Pop();
				GetElementInformation();
				break;
			case ElementState.LeafStart:
				_elementStack.Pop();
				GetElementInformation();
				break;
			case ElementState.LeafEnd:
			case ElementState.LoadEnd:
