namespace DocumentFormat.OpenXml.Packaging
{
	public class ExtendedPart : OpenXmlPart
	{
		private const string DefaultTargetExt = ".dat";

		private string _relationshipType;

		private static Dictionary<string, PartConstraintRule> _partConstraints = new Dictionary<string, PartConstraintRule>();

		private static Dictionary<string, PartConstraintRule> _dataPartReferenceConstraint = new Dictionary<string, PartConstraintRule>();

		public override string RelationshipType => _relationshipType;

		internal override string TargetFileExtension => ".dat";

		internal override string TargetPath => "udata";

		internal override string TargetName => "data";

		internal sealed override bool IsContentTypeFixed => false;

		protected ExtendedPart()
		{
		}

		protected internal ExtendedPart(string relationshipType)
		{
			_relationshipType = relationshipType;
		}

		internal sealed override IDictionary<string, PartConstraintRule> GetPartConstraint()
		{
			ThrowIfObjectDisposed();
			return _partConstraints;
		}

		internal sealed override IDictionary<string, PartConstraintRule> GetDataPartReferenceConstraint()
		{
			ThrowIfObjectDisposed();
			return _dataPartReferenceConstraint;
		}

		internal override bool IsInVersion(FileFormatVersions version)
		{
			return false;
		}

		internal override OpenXmlPart AddPartFrom(OpenXmlPart subPart, string rId)
		{
			ThrowIfObjectDisposed();
			if (subPart == null)
			{
				throw new ArgumentNullException("subPart");
			}
			if (subPart.OpenXmlPackage == InternalOpenXmlPackage && IsChildPart(subPart))
			{
				if (rId != null && rId != GetIdOfPart(subPart))
				{
					throw new InvalidOperationException(ExceptionMessages.PartExistsWithDifferentRelationshipId);
				}
				return subPart;
			}
			return AddSubPart(subPart, rId);
		}

		internal override void InitPart<T>(T newPart, string contentType, string id)
		{
			ThrowIfObjectDisposed();
			if (contentType == null)
			{
				throw new ArgumentNullException("contentType");
			}
			if (contentType == string.Empty)
			{
				throw new ArgumentException(ExceptionMessages.StringArgumentEmptyException, "contentType");
			}
			newPart.CreateInternal(InternalOpenXmlPackage, ThisOpenXmlPart, contentType, null);
			string key = AttachChild(newPart, id);
			base.ChildrenParts.Add(key, newPart);
		}
	}
}
namespace DocumentFormat.OpenXml
{
	internal class XmlDOMTextWriter : XmlTextWriter
	{
		public XmlDOMTextWriter(TextWriter w)
			: base(w)
		{
		}

		public XmlDOMTextWriter(Stream w, Encoding encoding)
			: base(w, encoding)
		{
		}

		public XmlDOMTextWriter(string filename, Encoding encoding)
			: base(filename, encoding)
		{
		}

		public override void WriteStartAttribute(string prefix, string localName, string ns)
		{
			if (string.IsNullOrEmpty(localName))
			{
				throw new ArgumentNullException("localName");
			}
			if (prefix == null)
			{
				prefix = string.Empty;
			}
			if (ns == null)
			{
				ns = string.Empty;
			}
			if (ns.Length == 0 && prefix.Length != 0)
			{
				prefix = string.Empty;
			}
			base.WriteStartAttribute(prefix, localName, ns);
		}

		public override void WriteStartElement(string prefix, string localName, string ns)
		{
			if (string.IsNullOrEmpty(localName))
			{
				throw new ArgumentNullException("localName");
			}
			if (prefix == null)
			{
				prefix = string.Empty;
			}
			if (ns == null)
			{
				ns = string.Empty;
			}
			if (ns.Length == 0 && prefix.Length != 0)
			{
				prefix = string.Empty;
			}
			base.WriteStartElement(prefix, localName, ns);
		}
	}
}
