				dictionary.Add("http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties", new PartConstraintRule("CustomFilePropertiesPart", "application/vnd.openxmlformats-officedocument.custom-properties+xml", minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2007 | FileFormatVersions.Office2010));
				dictionary.Add("http://schemas.openxmlformats.org/package/2006/relationships/metadata/thumbnail", new PartConstraintRule("ThumbnailPart", null, minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2007 | FileFormatVersions.Office2010));
				dictionary.Add("http://schemas.openxmlformats.org/package/2006/relationships/digital-signature/origin", new PartConstraintRule("DigitalSignatureOriginPart", "application/vnd.openxmlformats-package.digital-signature-origin", minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2007 | FileFormatVersions.Office2010));
				dictionary.Add("http://schemas.microsoft.com/office/2006/relationships/ui/userCustomization", new PartConstraintRule("QuickAccessToolbarCustomizationsPart", "application/xml", minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2007 | FileFormatVersions.Office2010));
				dictionary.Add("http://schemas.microsoft.com/office/2006/relationships/ui/extensibility", new PartConstraintRule("RibbonExtensibilityPart", "application/xml", minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2007 | FileFormatVersions.Office2010));
				dictionary.Add("http://schemas.microsoft.com/office/2007/relationships/ui/extensibility", new PartConstraintRule("RibbonAndBackstageCustomizationsPart", "application/xml", minOccursIsNonZero: false, maxOccursGreatThanOne: false, FileFormatVersions.Office2010));
				_partConstraint = dictionary;
			}
			return _partConstraint;
		}

		internal sealed override IDictionary<string, PartConstraintRule> GetDataPartReferenceConstraint()
		{
			if (_dataPartReferenceConstraint == null)
			{
				Dictionary<string, PartConstraintRule> dataPartReferenceConstraint = new Dictionary<string, PartConstraintRule>();
				_dataPartReferenceConstraint = dataPartReferenceConstraint;
			}
			return _dataPartReferenceConstraint;
		}

