		private void UpdateDocumentTypeFromContentType()
		{
			if (base.MainPartContentType == null)
			{
				throw new InvalidOperationException();
			}
			foreach (KeyValuePair<PresentationDocumentType, string> mainPartContentType in MainPartContentTypes)
			{
				if (mainPartContentType.Value == base.MainPartContentType)
				{
					DocumentType = mainPartContentType.Key;
				}
			}
		}

