namespace DocumentFormat.OpenXml.Validation
{
	internal abstract class DocumentValidator
	{
		internal SchemaValidator SchemaValidator { get; private set; }

		internal SemanticValidator SemanticValidator { get; private set; }

		protected ValidationSettings ValidationSettings { get; private set; }

		protected ValidationContext ValidationContext { get; set; }

		protected ValidationResult ValidationResult { get; set; }

		protected abstract OpenXmlPackage TargetDocument { get; set; }

		protected abstract IEnumerable<OpenXmlPart> PartsToBeValidated { get; }

		internal DocumentValidator(ValidationSettings settings, SchemaValidator schemaValidator, SemanticValidator semanticValidator)
		{
			SchemaValidator = schemaValidator;
			SemanticValidator = semanticValidator;
			ValidationSettings = settings;
		}

		internal ValidationResult Validate(OpenXmlPackage document)
		{
			TargetDocument = document;
			PrepareValidation();
			ValidationContext.Package = document;
			ValidatePackageStructure(document);
			foreach (OpenXmlPart item in PartsToBeValidated)
			{
				ValidatePart(item);
			}
			FinishValidation();
			return ValidationResult;
		}

		internal ValidationResult Validate(OpenXmlPart part)
		{
			PrepareValidation();
			ValidatePart(part);
			return ValidationResult;
		}

		internal void ValidatePart(OpenXmlPart part)
		{
			if (!part.IsInVersion(ValidationSettings.FileFormat))
			{
				return;
			}
			try
			{
				bool isRootElementLoaded = part.IsRootElementLoaded;
				ValidationContext.Part = part;
				ValidationContext.Element = part.PartRootElement;
				int count = ValidationResult.Errors.Count;
				if (part.PartRootElement != null)
				{
					SchemaValidator.Validate(ValidationContext);
					ValidationContext.Element = part.PartRootElement;
					SemanticValidator.ClearConstraintState(SemanticValidationLevel.PartOnly);
					SemanticValidator.Validate(ValidationContext);
				}
				if (!isRootElementLoaded && ValidationResult.Errors.Count == count)
				{
					part.SetPartRootElementToNull();
				}
			}
			catch (XmlException ex)
			{
				ValidationErrorInfo validationErrorInfo = new ValidationErrorInfo();
				validationErrorInfo.ErrorType = ValidationErrorType.Schema;
				validationErrorInfo.Id = "ExceptionError";
				validationErrorInfo.Part = part;
				validationErrorInfo.Path = new XmlPath(part);
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.ExceptionError, new object[1] { ex.Message });
				ValidationResult.AddError(validationErrorInfo);
			}
		}

		protected virtual bool PrepareValidation()
		{
			InitValidationContext();
			SemanticValidator.ClearConstraintState(SemanticValidationLevel.PackageOnly);
			return true;
		}

		protected void InitValidationContext()
		{
			ValidationResult = new ValidationResult();
			ValidationResult.Valid = true;
			ValidationResult.MaxNumberOfErrors = ValidationSettings.MaxNumberOfErrors;
			ValidationResult.MaxNumberOfErrorsEventHandler += SchemaValidator.OnCancel;
			ValidationResult.MaxNumberOfErrorsEventHandler += SemanticValidator.OnCancel;
			ValidationContext = new ValidationContext();
			ValidationContext.FileFormat = ValidationSettings.FileFormat;
			ValidationContext.ValidationErrorEventHandler += ValidationResult.OnValidationError;
		}

		protected virtual bool FinishValidation()
		{
			return true;
		}

		private void ValidatePackageStructure(OpenXmlPackage document)
		{
			OpenXmlPackageValidationSettings openXmlPackageValidationSettings = new OpenXmlPackageValidationSettings();
			openXmlPackageValidationSettings.EventHandler += OnPackageValidationError;
			document.Validate(openXmlPackageValidationSettings, ValidationSettings.FileFormat);
		}

		private void OnPackageValidationError(object sender, OpenXmlPackageValidationEventArgs e)
		{
			ValidationErrorInfo validationErrorInfo = new ValidationErrorInfo();
			validationErrorInfo.ErrorType = ValidationErrorType.Package;
			validationErrorInfo.Id = "Pkg_" + e.MessageId;
			switch (validationErrorInfo.Id)
			{
			case "Pkg_PartIsNotAllowed":
			{
				string text = ((e.Part != null) ? GetPartNameAndUri(e.Part) : GetDocumentName(TargetDocument));
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.Pkg_PartIsNotAllowed, new object[2]
				{
					text,
					GetPartNameAndUri(e.SubPart)
				});
				break;
			}
			case "Pkg_RequiredPartDoNotExist":
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.Pkg_RequiredPartDoNotExist, new object[1] { e.PartClassName });
				break;
			case "Pkg_OnlyOnePartAllowed":
			{
				string text = ((e.Part != null) ? GetPartNameAndUri(e.Part) : GetDocumentName(TargetDocument));
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.Pkg_OnlyOnePartAllowed, new object[2] { text, e.PartClassName });
				break;
			}
			case "Pkg_ExtendedPartIsOpenXmlPart":
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.Pkg_ExtendedPartIsOpenXmlPart, new object[1] { GetPartUri(e.SubPart) });
				break;
			case "Pkg_DataPartReferenceIsNotAllowed":
			{
				string text = ((e.Part != null) ? GetPartNameAndUri(e.Part) : GetDocumentName(TargetDocument));
				validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.Pkg_PartIsNotAllowed, new object[2]
				{
					text,
					e.DataPartReferenceRelationship.Uri
				});
				break;
			}
			}
			if (e.Part != null)
			{
				validationErrorInfo.Part = e.Part;
				validationErrorInfo.Path = new XmlPath(e.Part);
			}
			validationErrorInfo.RelatedPart = e.SubPart;
			ValidationResult.AddError(validationErrorInfo);
		}

		private static string GetPartNameAndUri(OpenXmlPart part)
		{
			string name = part.GetType().Name;
			return string.Format(CultureInfo.CurrentUICulture, "{0}{1}{2}{3}", name, '{', part.Uri, '}');
		}

		private static string GetPartUri(OpenXmlPart part)
		{
			return string.Format(CultureInfo.CurrentUICulture, "{0}{1}{2}", new object[3] { '{', part.Uri, '}' });
		}

		private static string GetDocumentName(OpenXmlPackage document)
		{
			return document.GetType().Name;
		}
	}
	internal class PresentationDocumentValidator : DocumentValidator
	{
		private PresentationDocument _presentationDocument;

		protected override OpenXmlPackage TargetDocument
		{
			get
			{
				return _presentationDocument;
			}
			set
			{
				_presentationDocument = (PresentationDocument)value;
			}
		}

		protected override IEnumerable<OpenXmlPart> PartsToBeValidated
		{
			get
			{
				PresentationPart mainPart = _presentationDocument.PresentationPart;
				if (mainPart == null)
				{
					yield break;
				}
				Dictionary<OpenXmlPart, bool> parts = new Dictionary<OpenXmlPart, bool>();
				_presentationDocument.FindAllReachableParts(parts);
				foreach (OpenXmlPart part in parts.Keys)
				{
					if (part.IsInVersion(base.ValidationSettings.FileFormat))
					{
						yield return part;
					}
				}
			}
		}

		internal PresentationDocumentValidator(ValidationSettings settings, SchemaValidator schemaValidator, SemanticValidator semanticValidator)
			: base(settings, schemaValidator, semanticValidator)
		{
		}
	}
