namespace DocumentFormat.OpenXml.Internal.SchemaValidation
{
	internal class AlternateContentValidator
	{
		internal static void Validate(ValidationContext validationContext)
		{
			AlternateContent alternateContent = (AlternateContent)validationContext.Element;
			ValidateMcAttributesOnAcb(validationContext, alternateContent);
			int num = 0;
			if (alternateContent.ChildElements.Count == 0)
			{
				ValidationErrorInfo error = validationContext.ComposeMcValidationError(alternateContent, "Sch_IncompleteContentExpectingComplex", ValidationResources.MC_ShallContainChoice);
				validationContext.EmitError(error);
			}
			for (OpenXmlElement openXmlElement = alternateContent.GetFirstNonMiscElementChild(); openXmlElement != null; openXmlElement = openXmlElement.GetNextNonMiscElementSibling())
			{
				if (openXmlElement is AlternateContent)
				{
					ValidationErrorInfo error = validationContext.ComposeMcValidationError(alternateContent, "Sch_InvalidElementContentExpectingComplex", openXmlElement.XmlQualifiedName.ToString(), ValidationResources.MC_ShallNotContainAlternateContent);
					validationContext.EmitError(error);
				}
				else
				{
					switch (num)
					{
					case 0:
					{
						if (openXmlElement is AlternateContentChoice)
						{
							ValidateMcAttributesOnAcb(validationContext, openXmlElement);
							num = 1;
							break;
						}
						ValidationErrorInfo error = validationContext.ComposeMcValidationError(alternateContent, "Sch_IncompleteContentExpectingComplex", ValidationResources.MC_ShallContainChoice);
						validationContext.EmitError(error);
						if (openXmlElement is AlternateContentFallback)
						{
							ValidateMcAttributesOnAcb(validationContext, openXmlElement);
						}
						break;
					}
					case 1:
					{
						if (openXmlElement is AlternateContentChoice)
						{
							ValidateMcAttributesOnAcb(validationContext, openXmlElement);
							num = 1;
							break;
						}
						if (openXmlElement is AlternateContentFallback)
						{
							ValidateMcAttributesOnAcb(validationContext, openXmlElement);
							num = 2;
							break;
						}
						ValidationErrorInfo error = validationContext.ComposeMcValidationError(alternateContent, "Sch_InvalidElementContentExpectingComplex", openXmlElement.XmlQualifiedName.ToString(), ValidationResources.MC_ShallContainChoice);
						validationContext.EmitError(error);
						break;
					}
					case 2:
					{
						ValidationErrorInfo error = validationContext.ComposeMcValidationError(alternateContent, "Sch_InvalidElementContentExpectingComplex", openXmlElement.XmlQualifiedName.ToString(), ValidationResources.MC_ShallContainChoice);
						validationContext.EmitError(error);
						break;
					}
					}
				}
			}
		}

		private static void ValidateMcAttributesOnAcb(ValidationContext validationContext, OpenXmlElement acElement)
		{
			if (acElement.ExtendedAttributes != null)
			{
				foreach (OpenXmlAttribute extendedAttribute in acElement.ExtendedAttributes)
				{
					if (string.IsNullOrEmpty(extendedAttribute.Prefix))
					{
						ValidationErrorInfo error = validationContext.ComposeMcValidationError(acElement, ValidationResources.MC_ErrorOnUnprefixedAttributeName, extendedAttribute.XmlQualifiedName.ToString());
						validationContext.EmitError(error);
					}
					if (IsXmlSpaceOrXmlLangAttribue(extendedAttribute))
					{
