		}

		public void AdjustState()
		{
			if (_stateStack.Count() != 0)
			{
				_values = _stateStack.Pop();
			}
			else
			{
				_values = null;
			}
		}

		public override void ClearState(ValidationContext context)
		{
			if (context == null)
			{
