				_childMatchInfo.Reset(openXmlElement);
				TryMatchOnce(_childMatchInfo, validationContext);
				if (_childMatchInfo.Match == ParticleMatch.Nomatch)
				{
					break;
				}
				if (_childMatchInfo.Match == ParticleMatch.Matched)
				{
					num++;
					particleMatchInfo.LastMatchedElement = _childMatchInfo.LastMatchedElement;
					openXmlElement = validationContext.GetNextChildMc(particleMatchInfo.LastMatchedElement);
					continue;
				}
				particleMatchInfo.Match = ParticleMatch.Partial;
				particleMatchInfo.LastMatchedElement = _childMatchInfo.LastMatchedElement;
