			OpenXmlElement element = validationContext.Element;
			firstChildMc = ((particleMatchInfo.LastMatchedElement != null) ? validationContext.GetNextChildMc(particleMatchInfo.LastMatchedElement) : validationContext.GetFirstChildMc());
			string text = null;
			ValidationErrorInfo error;
			switch (particleMatchInfo.Match)
			{
			case ParticleMatch.Nomatch:
				text = ParticleValidator.GetExpectedChildrenMessage(validationContext.Element, GetExpectedElements());
				break;
			case ParticleMatch.Partial:
