					error = validationContext.ComposeSchemaValidationError(element, null, "Sch_IncompleteContentExpectingComplex", ParticleValidator.GetExpectedChildrenMessage(element, particleMatchInfo.ExpectedChildren));
					validationContext.EmitError(error);
					return;
				}
				text = ParticleValidator.GetExpectedChildrenMessage(validationContext.Element, particleMatchInfo.ExpectedChildren);
				break;
			case ParticleMatch.Matched:
				text = ((!ParticleConstraint.CanOccursMoreThanOne) ? ParticleValidator.GetExpectedChildrenMessage(validationContext.Element, particleMatchInfo.ExpectedChildren) : ParticleValidator.GetExpectedChildrenMessage(validationContext.Element, GetExpectedElements()));
