				error = ((openXmlElement != null) ? validationContext.ComposeSchemaValidationError(element, firstChildMc, "Sch_InvalidElementContentWrongType", firstChildMc.XmlQualifiedName.ToString(), firstChildMc.GetType().Name) : validationContext.ComposeSchemaValidationError(element, firstChildMc, "Sch_InvalidElementContentExpectingComplex", firstChildMc.XmlQualifiedName.ToString(), text));
