			particleMatchInfo.Match = ParticleMatch.Matched;
			ParticleConstraint[] childrenParticles3 = base.ParticleConstraint.ChildrenParticles;
			foreach (ParticleConstraint particleConstraint3 in childrenParticles3)
			{
