	internal class SchemaValidator : ICancelable
	{
		private SdbSchemaDatas _sdbSchemaDatas;

		private SchemaTypeValidator _schemaTypeValidator;

		private bool _stopValidating;

		internal SchemaValidator()
			: this(FileFormatVersions.Office2007)
		{
		}

		internal SchemaValidator(FileFormatVersions fileFormat)
		{
			switch (fileFormat)
			{
			case FileFormatVersions.Office2007:
				_sdbSchemaDatas = SdbSchemaDatas.GetOffice2007SchemaDatas();
				break;
			case FileFormatVersions.Office2010:
				_sdbSchemaDatas = SdbSchemaDatas.GetOffice2010SchemaDatas();
				break;
			default:
			{
				string message = string.Format(CultureInfo.CurrentUICulture, ExceptionMessages.FileFormatShouldBe2007Or2010, new object[1] { fileFormat });
				throw new ArgumentOutOfRangeException("fileFormat", message);
			}
			}
			_schemaTypeValidator = new SchemaTypeValidator(_sdbSchemaDatas);
		}

		internal void Validate(ValidationContext validationContext)
		{
			_stopValidating = false;
			_ = validationContext.Element;
			ValidationTraverser.ValidatingTraverse(validationContext, ValidateElement, null, StopSignal);
		}

		private void ValidateElement(ValidationContext validationContext)
		{
			_schemaTypeValidator.Validate(validationContext);
		}

		private bool StopSignal(ValidationContext validationContext)
		{
			return _stopValidating;
		}

		public void OnCancel(object sender, EventArgs eventArgs)
		{
			_stopValidating = true;
		}
	}
	internal static class ValidationContextExtension
	{
		internal static ValidationErrorInfo ComposeSchemaValidationError(this ValidationContext validationContext, OpenXmlElement element, OpenXmlElement child, string messageId, params string[] args)
		{
			return validationContext.ComposeValidationError(ValidationErrorType.Schema, element, child, messageId, args);
		}

		internal static ValidationErrorInfo ComposeMcValidationError(this ValidationContext validationContext, OpenXmlElement element, string messageId, params string[] args)
		{
			return validationContext.ComposeValidationError(ValidationErrorType.MarkupCompatibility, element, null, messageId, args);
		}

		internal static ValidationErrorInfo ComposeValidationError(this ValidationContext validationContext, ValidationErrorType errorType, OpenXmlElement element, OpenXmlElement child, string messageId, params string[] args)
		{
			ValidationErrorInfo validationErrorInfo = new ValidationErrorInfo();
			validationErrorInfo.ErrorType = errorType;
			validationErrorInfo.Part = validationContext.Part;
			validationErrorInfo.Node = element;
			validationErrorInfo.Id = messageId;
			validationErrorInfo.RelatedNode = child;
			validationErrorInfo.Description = string.Format(CultureInfo.CurrentUICulture, ValidationResources.ResourceManager.GetString(messageId), args);
			return validationErrorInfo;
		}
	}
	internal class SdbSchemaDatas
	{
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private ParticleConstraint[] EmptyChildrenParticles = new ParticleConstraint[0];

		private Dictionary<ushort, SchemaTypeData> _schemaTypeDatas;

		private bool _loaded;

		private FileFormatVersions _fileFormat;

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SdbDataArray<SdbClassIdToSchemaTypeIndex> SdbClassIdMap { get; set; }

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SdbDataArray<SdbSchemaType> SdbSchemaTypes { get; set; }

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SdbDataArray<SdbParticleConstraint> SdbParticles { get; set; }

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SdbDataArray<SdbParticleChildrenIndex> SdbParticleIndexs { get; set; }

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SdbDataArray<SdbAttributeConstraint> SdbAttributes { get; set; }

		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private SimpleTypeRestrictions SimpleTypeRestrictions { get; set; }

		public SdbDataHead SdbDataHead { get; private set; }

		private SdbSchemaDatas(FileFormatVersions fileFormat)
		{
			SdbDataHead = new SdbDataHead();
			_fileFormat = fileFormat;
		}

		public static SdbSchemaDatas GetOffice2007SchemaDatas()
		{
			SdbSchemaDatas sdbSchemaDatas = new SdbSchemaDatas(FileFormatVersions.Office2007);
			sdbSchemaDatas.InitOnDemand();
			return sdbSchemaDatas;
		}

		public static SdbSchemaDatas GetOffice2010SchemaDatas()
		{
			SdbSchemaDatas sdbSchemaDatas = new SdbSchemaDatas(FileFormatVersions.Office2010);
			sdbSchemaDatas.InitOnDemand();
			return sdbSchemaDatas;
		}

		internal SchemaTypeData GetSchemaTypeData(OpenXmlElement openxmlElement)
		{
			return GetSchemaTypeData(openxmlElement.ElementTypeId);
		}

		internal SchemaTypeData GetSchemaTypeData(int openxmlTypeId)
		{
			InitOnDemand();
			ushort num = (ushort)openxmlTypeId;
			if (_schemaTypeDatas.TryGetValue(num, out var value))
			{
				return value;
			}
			value = LoadSchemaTypeData(num);
			_schemaTypeDatas.Add(num, value);
			return value;
		}

		private void InitOnDemand()
		{
			if (!_loaded)
			{
				Init();
			}
		}

		private void Init()
		{
			_schemaTypeDatas = new Dictionary<ushort, SchemaTypeData>();
			using MemoryStream dataStream = new MemoryStream(_fileFormat switch
			{
				FileFormatVersions.Office2007 => ValidationResources.O12SchemaConstraintDatas, 
				FileFormatVersions.Office2010 => ValidationResources.O14SchemaConstraintDatas, 
				_ => ValidationResources.O12SchemaConstraintDatas, 
			}, writable: false);
			Load(dataStream);
		}

		private SchemaTypeData LoadSchemaTypeData(ushort openxmlTypeId)
		{
			ushort index = (ushort)(openxmlTypeId - SdbDataHead.StartClassId);
			SdbSchemaType sdbSchemaType = SdbSchemaTypes[SdbClassIdMap[index].SchemaTypeIndex];
			AttributeConstraint[] attributeConstraints = BuildAttributeConstraint(sdbSchemaType);
			ParticleConstraint particleConstraint = BuildParticleConstraint(sdbSchemaType);
			if (particleConstraint != null)
			{
				return new SchemaTypeData(openxmlTypeId, attributeConstraints, particleConstraint);
			}
			if (sdbSchemaType.IsSimpleContent)
			{
				SimpleTypeRestriction simpleTypeConstraint = SimpleTypeRestrictions[sdbSchemaType.SimpleTypeIndex];
				return new SchemaTypeData(openxmlTypeId, attributeConstraints, simpleTypeConstraint);
			}
			return new SchemaTypeData(openxmlTypeId, attributeConstraints);
		}

		private ParticleConstraint BuildParticleConstraint(SdbSchemaType sdbSchemaTpye)
		{
			if (sdbSchemaTpye.IsCompositeType)
			{
				return BuildParticleConstraint(sdbSchemaTpye.ParticleIndex);
			}
			return null;
		}

		private ParticleConstraint BuildParticleConstraint(ushort particleIndex)
		{
			SdbParticleConstraint sdbParticleConstraint = SdbParticles[particleIndex];
			ParticleConstraint particleConstraint = ParticleConstraint.CreateParticleConstraint(sdbParticleConstraint.ParticleType);
			particleConstraint.ParticleType = sdbParticleConstraint.ParticleType;
			particleConstraint.MaxOccurs = sdbParticleConstraint.MaxOccurs;
			particleConstraint.MinOccurs = sdbParticleConstraint.MinOccurs;
			particleConstraint.ElementId = sdbParticleConstraint.ElementTypeId;
			if (sdbParticleConstraint.ChildrenCount > 0)
			{
				particleConstraint.ChildrenParticles = new ParticleConstraint[sdbParticleConstraint.ChildrenCount];
				for (ushort num = 0; num < sdbParticleConstraint.ChildrenCount; num++)
				{
					ushort particleIndex2 = SdbParticleIndexs[(ushort)(sdbParticleConstraint.ChildrenStartIndex + num)].ParticleIndex;
					particleConstraint.ChildrenParticles[num] = BuildParticleConstraint(particleIndex2);
				}
			}
			else if (sdbParticleConstraint.ParticleType == ParticleType.All || sdbParticleConstraint.ParticleType == ParticleType.Choice || sdbParticleConstraint.ParticleType == ParticleType.Group || sdbParticleConstraint.ParticleType == ParticleType.Sequence)
			{
				particleConstraint.ChildrenParticles = EmptyChildrenParticles;
			}
			return particleConstraint;
		}

		private AttributeConstraint[] BuildAttributeConstraint(SdbSchemaType sdbSchemaTpye)
		{
			if (sdbSchemaTpye.AttributesCount > 0)
			{
				int attributesCount = sdbSchemaTpye.AttributesCount;
				AttributeConstraint[] array = new AttributeConstraint[attributesCount];
				ushort startIndexOfAttributes = sdbSchemaTpye.StartIndexOfAttributes;
				for (int i = 0; i < attributesCount; i++)
				{
					SdbAttributeConstraint sdbAttributeConstraint = SdbAttributes[startIndexOfAttributes + i];
					ushort simpleTypeIndex = sdbAttributeConstraint.SimpleTypeIndex;
					SimpleTypeRestriction simpleTypeConstraint = SimpleTypeRestrictions[simpleTypeIndex];
					array[i] = new AttributeConstraint(sdbAttributeConstraint.AttributeUse, simpleTypeConstraint, (FileFormatVersions)sdbAttributeConstraint.FileFormatVersion);
				}
				return array;
			}
			return null;
		}

		internal void Load(Stream dataStream)
		{
			byte[] array = new byte[128];
			dataStream.Read(array, 0, 128);
			SdbDataHead.LoadFromBytes(array, 0);
			CheckDataHead((int)dataStream.Length);
			int num = SdbDataHead.ClassIdsCount * SdbClassIdToSchemaTypeIndex.TypeSize;
			byte[] array2 = new byte[num];
			dataStream.Read(array2, 0, num);
			SdbClassIdMap = new SdbDataArray<SdbClassIdToSchemaTypeIndex>(array2);
			num = SdbDataHead.SchemaTypeCount * SdbSchemaType.TypeSize;
			array2 = new byte[num];
			dataStream.Read(array2, 0, num);
			SdbSchemaTypes = new SdbDataArray<SdbSchemaType>(array2);
			num = SdbDataHead.ParticleCount * SdbParticleConstraint.TypeSize;
			array2 = new byte[num];
			dataStream.Read(array2, 0, num);
			SdbParticles = new SdbDataArray<SdbParticleConstraint>(array2);
			num = SdbDataHead.ParticleChildrenIndexCount * SdbParticleChildrenIndex.TypeSize;
			array2 = new byte[num];
			dataStream.Read(array2, 0, num);
			SdbParticleIndexs = new SdbDataArray<SdbParticleChildrenIndex>(array2);
			num = SdbDataHead.AttributeCount * SdbAttributeConstraint.TypeSize;
			array2 = new byte[num];
			dataStream.Read(array2, 0, num);
			SdbAttributes = new SdbDataArray<SdbAttributeConstraint>(array2);
			dataStream.Seek(SdbDataHead.SimpleTypeDataOffset, SeekOrigin.Begin);
			SimpleTypeRestrictions = SimpleTypeRestrictions.Deserialize(dataStream, _fileFormat);
			Assert(SdbDataHead.SimpleTypeCount == SimpleTypeRestrictions.SimpleTypeCount);
			CheckData();
			_loaded = true;
		}

		private SdbClassIdToSchemaTypeIndex GetClassIdData(ushort classId)
		{
			int index = SdbClassIdToSchemaTypeIndex.ArrayIndexFromClassId(classId);
			return SdbClassIdMap[index];
		}

		private void CheckDataHead(int streamLength)
		{
			SdbDataHead sdbDataHead = SdbDataHead;
			Assert(sdbDataHead.StartClassId == 10001);
			Assert(sdbDataHead.DataByteCount + 256 == streamLength);
			Assert(sdbDataHead.ClassIdsCount > 0);
			Assert(sdbDataHead.SchemaTypeCount > 0);
			Assert(sdbDataHead.SchemaTypeDataOffset == sdbDataHead.ClassIdsDataOffset + sdbDataHead.ClassIdsCount * SdbClassIdToSchemaTypeIndex.TypeSize);
			Assert(sdbDataHead.ParticleCount > 0);
			Assert(sdbDataHead.ParticleDataOffset == sdbDataHead.SchemaTypeDataOffset + sdbDataHead.SchemaTypeCount * SdbSchemaType.TypeSize);
			Assert(sdbDataHead.ParticleChildrenIndexCount > 0);
			Assert(sdbDataHead.ParticleChildrenIndexDataOffset == sdbDataHead.ParticleDataOffset + sdbDataHead.ParticleCount * SdbParticleConstraint.TypeSize);
			Assert(sdbDataHead.AttributeCount > 0);
			Assert(sdbDataHead.AttributeDataOffset == sdbDataHead.ParticleChildrenIndexDataOffset + sdbDataHead.ParticleChildrenIndexCount * SdbParticleChildrenIndex.TypeSize);
			Assert(sdbDataHead.SimpleTypeCount > 0);
			Assert(sdbDataHead.SimpleTypeDataOffset == sdbDataHead.AttributeDataOffset + sdbDataHead.AttributeCount * SdbAttributeConstraint.TypeSize);
			Assert(sdbDataHead.SimpleTypeDataOffset < streamLength);
		}

		private static void Assert(bool value)
		{
			if (!value)
			{
				throw new InvalidDataException("Invalid schema constraint binary data.");
			}
		}

		private void CheckData()
		{
		}
	}
	internal class SdbDataArray<T> where T : SdbData, new()
	{
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private byte[] _sdbDataBytes;

		public T this[int index]
		{
			get
			{
				T result = new T();
				result.LoadFromBytes(_sdbDataBytes, index * result.DataSize);
				return result;
			}
		}

		public SdbDataArray(byte[] sdbDataBytes)
		{
			_sdbDataBytes = sdbDataBytes;
		}
	}
	internal class SequenceParticleValidator : CompositeParticleValidator
	{
		private ParticleMatchInfo _childMatchInfo = new ParticleMatchInfo();

		internal SequenceParticleValidator(CompositeParticle particleConstraint)
			: base(particleConstraint)
		{
		}

		public override void TryMatchOnce(ParticleMatchInfo particleMatchInfo, ValidationContext validationContext)
		{
			OpenXmlElement openXmlElement = particleMatchInfo.StartElement;
			particleMatchInfo.LastMatchedElement = null;
			particleMatchInfo.Match = ParticleMatch.Nomatch;
			int i = 0;
			int num = base.ParticleConstraint.ChildrenParticles.Length;
			while (i < num && openXmlElement != null)
			{
				ParticleConstraint particleConstraint = base.ParticleConstraint.ChildrenParticles[i];
				_childMatchInfo.Reset(openXmlElement);
				particleConstraint.ParticleValidator.TryMatch(_childMatchInfo, validationContext);
				switch (_childMatchInfo.Match)
				{
				case ParticleMatch.Nomatch:
					if (particleConstraint.ParticleValidator.GetRequiredElements(null))
					{
						if (validationContext.CollectExpectedChildren)
						{
							if (particleMatchInfo.ExpectedChildren == null)
							{
								particleMatchInfo.SetExpectedChildren(particleConstraint.ParticleValidator.GetRequiredElements());
							}
							else
							{
								particleMatchInfo.ExpectedChildren.Clear();
								particleConstraint.ParticleValidator.GetRequiredElements(particleMatchInfo.ExpectedChildren);
							}
						}
						if (openXmlElement == particleMatchInfo.StartElement)
						{
							particleMatchInfo.Match = ParticleMatch.Nomatch;
							particleMatchInfo.LastMatchedElement = null;
						}
						else
						{
							particleMatchInfo.Match = ParticleMatch.Partial;
						}
						return;
					}
					i++;
					break;
				case ParticleMatch.Matched:
					particleMatchInfo.LastMatchedElement = _childMatchInfo.LastMatchedElement;
					openXmlElement = validationContext.GetNextChildMc(particleMatchInfo.LastMatchedElement);
					i++;
					break;
				case ParticleMatch.Partial:
					particleMatchInfo.Match = ParticleMatch.Partial;
					particleMatchInfo.LastMatchedElement = _childMatchInfo.LastMatchedElement;
					if (validationContext.CollectExpectedChildren)
					{
						particleMatchInfo.SetExpectedChildren(_childMatchInfo.ExpectedChildren);
					}
					return;
				}
			}
			if (i == num)
			{
				if (particleMatchInfo.LastMatchedElement != null)
				{
					particleMatchInfo.Match = ParticleMatch.Matched;
				}
				else
				{
					particleMatchInfo.Match = ParticleMatch.Nomatch;
				}
				return;
			}
			for (; i < num; i++)
			{
				if (!base.ParticleConstraint.ChildrenParticles[i].ParticleValidator.GetRequiredElements(null))
				{
					continue;
				}
				if (validationContext.CollectExpectedChildren)
				{
					if (particleMatchInfo.ExpectedChildren == null)
					{
						particleMatchInfo.InitExpectedChildren();
					}
					base.ParticleConstraint.ChildrenParticles[i].ParticleValidator.GetRequiredElements(particleMatchInfo.ExpectedChildren);
				}
				particleMatchInfo.Match = ParticleMatch.Partial;
				return;
			}
			particleMatchInfo.Match = ParticleMatch.Matched;
		}

		public override bool GetRequiredElements(ExpectedChildren result)
		{
			bool result2 = false;
			if (base.ParticleConstraint.MinOccurs > 0)
			{
				ParticleConstraint[] childrenParticles = base.ParticleConstraint.ChildrenParticles;
				foreach (ParticleConstraint particleConstraint in childrenParticles)
				{
					if (particleConstraint.ParticleValidator.GetRequiredElements(result))
					{
						result2 = true;
						break;
					}
				}
			}
			return result2;
		}

		public override bool GetExpectedElements(ExpectedChildren result)
		{
			if (base.ParticleConstraint.ChildrenParticles.Length > 0)
			{
				base.ParticleConstraint.ChildrenParticles[0].ParticleValidator.GetExpectedElements(result);
				return true;
			}
			return false;
		}
	}
