	[Serializable]
	internal class SimpleTypeRestrictions
	{
		public int SimpleTypeCount { get; set; }

		public SimpleTypeRestriction[] SimpleTypes { get; set; }

		public SimpleTypeRestriction this[int index] => SimpleTypes[index];

		internal void Serialize(Stream stream)
		{
			BinaryFormatter binaryFormatter = new BinaryFormatter();
			binaryFormatter.AssemblyFormat = FormatterAssemblyStyle.Full;
			binaryFormatter.Serialize(stream, this);
		}

		internal static SimpleTypeRestrictions Deserialize(Stream stream, FileFormatVersions fileFormat)
		{
			BinaryFormatter binaryFormatter = new BinaryFormatter();
			binaryFormatter.AssemblyFormat = FormatterAssemblyStyle.Full;
			SimpleTypeRestrictions simpleTypeRestrictions = (SimpleTypeRestrictions)binaryFormatter.Deserialize(stream);
			SimpleTypeRestriction[] simpleTypes = simpleTypeRestrictions.SimpleTypes;
			foreach (SimpleTypeRestriction simpleTypeRestriction in simpleTypes)
			{
