		{
			return restrictionField switch
			{
				RestrictionField.MinExclusive => MinExclusive.ToString(), 
				RestrictionField.MaxExclusive => MaxExclusive.ToString(), 
				RestrictionField.MinInclusive => MinInclusive.ToString(), 
				RestrictionField.MaxInclusive => MaxInclusive.ToString(), 
				_ => base.GetRestrictionValue(restrictionField), 
			};
		}

		public virtual OpenXmlSimpleValue<T> StringToSimpleValue(string valueText)
		{
			if (string.IsNullOrEmpty(valueText))
