		{
			ST val = (ST)attributeValue;
			if ((base.RestrictionField & RestrictionField.MinInclusive) == RestrictionField.MinInclusive && MinInclusive.CompareTo(val.Value) > 0)
			{
				return false;
			}
			return true;
		}

		public override bool IsMinExclusiveValid(OpenXmlSimpleType attributeValue)
		{
			ST val = (ST)attributeValue;
			if ((base.RestrictionField & RestrictionField.MinExclusive) == RestrictionField.MinExclusive && MinExclusive.CompareTo(val.Value) >= 0)
			{
				return false;
			}
			return true;
		}

		public override bool IsMaxInclusiveValid(OpenXmlSimpleType attributeValue)
		{
			ST val = (ST)attributeValue;
			if ((base.RestrictionField & RestrictionField.MaxInclusive) == RestrictionField.MaxInclusive && MaxInclusive.CompareTo(val.Value) < 0)
			{
				return false;
			}
			return true;
		}

		public override bool IsMaxExclusiveValid(OpenXmlSimpleType attributeValue)
		{
			ST val = (ST)attributeValue;
			if ((base.RestrictionField & RestrictionField.MaxExclusive) == RestrictionField.MaxExclusive && MaxExclusive.CompareTo(val.Value) <= 0)
			{
				return false;
			}
			return true;
		}

		public override bool ValidateValueType(OpenXmlSimpleType attributeValue)
		{
			if (attributeValue.HasValue)
			{
				ST val = (ST)attributeValue;
				if (val.Value.CompareTo(MinValue) < 0 || val.Value.CompareTo(MaxValue) > 0)
				{
					return false;
				}
				return true;
			}
			return false;
		}
	}
