namespace DocumentFormat.OpenXml.Validation
{
	internal class ValidationContext
	{
		internal FileFormatVersions FileFormat { get; set; }

		internal OpenXmlPackage Package { get; set; }

		internal OpenXmlPart Part { get; set; }

		internal OpenXmlElement Element { get; set; }

		internal MCContext McContext { get; set; }

		internal bool CollectExpectedChildren { get; set; }

		internal event EventHandler<ValidationErrorEventArgs> ValidationErrorEventHandler;

		internal ValidationContext()
		{
			McContext = new MCContext(exceptionOnError: false);
			FileFormat = FileFormatVersions.Office2007;
		}

		internal void EmitError(ValidationErrorInfo error)
		{
			OnValidationError(new ValidationErrorEventArgs(error));
		}

		protected virtual void OnValidationError(ValidationErrorEventArgs errorEventArgs)
		{
			this.ValidationErrorEventHandler?.Invoke(this, errorEventArgs);
		}

		internal OpenXmlElement GetFirstChildMc()
		{
			return Element.GetFirstChildMc(McContext, FileFormat);
		}

		internal OpenXmlElement GetNextChildMc(OpenXmlElement child)
		{
			return Element.GetNextChildMc(child, McContext, FileFormat);
		}
	}
	internal class ValidationErrorEventArgs : EventArgs
	{
		internal ValidationErrorInfo ValidationErrorInfo { get; set; }

		internal ValidationErrorEventArgs(ValidationErrorInfo validatoinError)
		{
			ValidationErrorInfo = validatoinError;
		}
	}
	public enum ValidationErrorType
	{
		Schema,
		Semantic,
		Package,
		MarkupCompatibility
	}
	[DebuggerDisplay("Description={Description}")]
	public class ValidationErrorInfo
	{
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private OpenXmlElement _element;

		public string Id { get; internal set; }

		public ValidationErrorType ErrorType { get; internal set; }

		public string Description { get; internal set; }

		public XmlPath Path { get; internal set; }

		public OpenXmlElement Node
		{
			get
			{
				return _element;
			}
			internal set
			{
				_element = value;
				Path = XmlPath.GetXPath(value);
				if (Part == null)
				{
					Part = _element.GetPart();
				}
			}
		}

		public OpenXmlPart Part { get; internal set; }

		public OpenXmlElement RelatedNode { get; internal set; }

		public OpenXmlPart RelatedPart { get; internal set; }

		[Conditional("DEBUG")]
		public void SetDebugField(string attributeQualifiedName, string validationErrorCategory)
		{
		}
	}
	internal class ValidationResult
	{
		internal bool Canceled { get; set; }

		internal bool Valid { get; set; }

		internal List<ValidationErrorInfo> Errors { get; private set; }

		internal int MaxNumberOfErrors { get; set; }

		internal event EventHandler<EventArgs> MaxNumberOfErrorsEventHandler;

		internal ValidationResult()
		{
			Valid = true;
			Errors = new List<ValidationErrorInfo>();
		}

		internal void Clear()
		{
			Valid = true;
			Canceled = false;
			Errors.Clear();
		}

		internal void AddError(ValidationErrorInfo error)
		{
			Valid = false;
			Errors.Add(error);
		}

		internal void OnValidationError(object sender, ValidationErrorEventArgs errorEventArgs)
		{
			if (errorEventArgs.ValidationErrorInfo != null)
			{
				if (MaxNumberOfErrors > 0 && Errors.Count >= MaxNumberOfErrors)
				{
					this.MaxNumberOfErrorsEventHandler?.Invoke(this, null);
					return;
				}
				Valid = false;
				Errors.Add(errorEventArgs.ValidationErrorInfo);
			}
		}
	}
}
namespace DocumentFormat.OpenXml
{
	internal class ValidationSettings
	{
		private const int _defaultMaxNumberOfErrorsReturned = 1000;

		internal FileFormatVersions FileFormat { get; set; }

		internal int MaxNumberOfErrors { get; set; }

		internal ValidationSettings()
		{
			FileFormat = FileFormatVersions.Office2007;
			MaxNumberOfErrors = 1000;
		}

		internal ValidationSettings(FileFormatVersions fileFormat)
		{
			fileFormat.ThrowExceptionIfNot2007Or2010("fileFormat");
			FileFormat = fileFormat;
			MaxNumberOfErrors = 1000;
		}
	}
