namespace DocumentFormat.OpenXml.Validation
{
	internal static class ValidationTraverser
	{
		internal delegate void ValidationAction(ValidationContext validationContext);

		internal delegate bool GetStopSignal(ValidationContext validationContext);

		internal static void ValidatingTraverse(ValidationContext validationContext, ValidationAction validateAction, ValidationAction finishAction, GetStopSignal getStopSignal)
		{
			if (getStopSignal != null && getStopSignal(validationContext))
			{
				return;
			}
			OpenXmlElement element = validationContext.Element;
			bool flag = false;
			validationContext.McContext.PushMCAttributes2(element.MCAttributes, (string prefix) => element.LookupNamespace(prefix));
			if (element.IsStrongTypedElement())
			{
				if (element.IsInVersion(validationContext.FileFormat))
				{
					validateAction(validationContext);
					flag = true;
				}
				else
				{
					validationContext.McContext.IsProcessContent(element);
				}
				foreach (OpenXmlElement childElement in element.ChildElements)
				{
					validationContext.Element = childElement;
					ValidatingTraverse(validationContext, validateAction, finishAction, getStopSignal);
				}
			}
			else if (element.ElementTypeId == 9002 || element.ElementTypeId == 9002)
			{
				if (validationContext.McContext.IsProcessContent(element))
				{
					foreach (OpenXmlElement childElement2 in element.ChildElements)
					{
						validationContext.Element = childElement2;
						ValidatingTraverse(validationContext, validateAction, finishAction, getStopSignal);
					}
				}
			}
			else if (element.ElementTypeId == 9003)
			{
				validateAction(validationContext);
				flag = true;
				OpenXmlCompositeElement contentFromACBlock = validationContext.McContext.GetContentFromACBlock((AlternateContent)element, validationContext.FileFormat);
				if (contentFromACBlock != null)
				{
					foreach (OpenXmlElement childElement3 in contentFromACBlock.ChildElements)
					{
						validationContext.Element = childElement3;
						ValidatingTraverse(validationContext, validateAction, finishAction, getStopSignal);
					}
				}
			}
			else
			{
				_ = element.ElementTypeId;
				_ = 9001;
			}
			validationContext.McContext.PopMCAttributes2();
			if (flag && finishAction != null)
			{
				validationContext.Element = element;
				finishAction(validationContext);
			}
		}
	}
	internal class WordprocessingDocumentValidator : DocumentValidator
	{
		private WordprocessingDocument _wordprossingDocument;

		protected override OpenXmlPackage TargetDocument
		{
			get
			{
				return _wordprossingDocument;
			}
			set
			{
				_wordprossingDocument = (WordprocessingDocument)value;
			}
		}

		protected override IEnumerable<OpenXmlPart> PartsToBeValidated
		{
			get
			{
				MainDocumentPart mainPart = _wordprossingDocument.MainDocumentPart;
				if (mainPart == null)
				{
					yield break;
				}
				Dictionary<OpenXmlPart, bool> parts = new Dictionary<OpenXmlPart, bool>();
				_wordprossingDocument.FindAllReachableParts(parts);
				foreach (OpenXmlPart part in parts.Keys)
				{
					if (part.IsInVersion(base.ValidationSettings.FileFormat))
					{
						yield return part;
					}
				}
			}
		}

		internal WordprocessingDocumentValidator(ValidationSettings settings, SchemaValidator schemaValidator, SemanticValidator semanticValidator)
			: base(settings, schemaValidator, semanticValidator)
		{
		}
	}
}
namespace DocumentFormat.OpenXml
{
	[DebuggerDisplay("XPath={XPath}")]
	public class XmlPath
	{
		private List<string> _namespacesDefinitions = new List<string>();

		public IList<string> NamespacesDefinitions => _namespacesDefinitions;

		public string XPath { get; private set; }

		public Uri PartUri { get; private set; }

		private XmlPath()
		{
		}

		internal XmlPath(OpenXmlPart part)
		{
			PartUri = part.Uri;
		}

		internal static XmlPath GetXPath(OpenXmlElement element)
		{
			if (element == null)
			{
				return null;
			}
			XmlPath xmlPath = new XmlPath();
			xmlPath.PartUri = element.GetPartUri();
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			StringBuilder stringBuilder = new StringBuilder("");
			BuildXPath(element, stringBuilder, dictionary);
			xmlPath.XPath = stringBuilder.ToString();
			foreach (KeyValuePair<string, string> item in dictionary)
			{
				StringBuilder stringBuilder2 = new StringBuilder("");
				stringBuilder2.Append("xmlns:");
				stringBuilder2.Append(item.Key);
				stringBuilder2.Append("=\"");
				stringBuilder2.Append(item.Value);
				stringBuilder2.Append("\"");
				xmlPath.NamespacesDefinitions.Add(stringBuilder2.ToString());
			}
			return xmlPath;
		}

		internal static void BuildXPath(OpenXmlElement element, StringBuilder xpath, Dictionary<string, string> namespaces)
		{
			if (element.Parent != null)
			{
				BuildXPath(element.Parent, xpath, namespaces);
			}
			xpath.Append("/");
			if (element is OpenXmlMiscNode)
			{
				xpath.Append(element.OuterXml);
				return;
			}
			if (!string.IsNullOrEmpty(element.Prefix))
			{
				if (!namespaces.ContainsKey(element.Prefix))
				{
					namespaces.Add(element.Prefix, element.NamespaceUri);
				}
				xpath.Append(element.Prefix);
				xpath.Append(":");
			}
			else if (!string.IsNullOrEmpty(element.NamespaceUri))
			{
				xpath.Append(element.NamespaceUri);
				xpath.Append(":");
			}
			xpath.Append(element.LocalName);
			xpath.Append("[");
			xpath.Append(element.GetXPathIndex());
			xpath.Append("]");
		}
	}
}
